    """
def listify[T](
    value: T,
    return_empty_list_if_none: bool = True,
    convert_tuple_to_list: bool = True
) -> list {
    if not isinstance(value, list) {
        if value is None and return_empty_list_if_none {
            value = [];
        } elif isinstance(value, tuple) and convert_tuple_to_list {
            value = list(value);
        } else {
            value = [value];
        }
    }
    return value;
}

